import React, { useContext, useEffect, useRef, useState } from "react";
import noteContext from "../context/notes/noteContext";
import { useNavigate } from "react-router-dom";
import Noteitem from "./Noteitem";
import AddNote from "./AddNote";

const Notes = (props) => {
  const context = useContext(noteContext);
  let navigate = useNavigate();
  const { notes, getNotes, editNote } = context;
  
  useEffect(() => {
    if(localStorage.getItem('token')){
      getNotes();
    }
    else{
      navigate("/login")
    }
    // eslint-disable-next-line
  }, []);
  
  const ref = useRef(null);
  const refClose = useRef(null);
  const [note, setNote] = useState({
    id: "",
    etitle: "",
    edescription: "",
    etag: ""
  });
  
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedTag, setSelectedTag] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);

  const updateNote = (currentNote) => {
    setNote({
      id: currentNote._id,
      etitle: currentNote.title,
      edescription: currentNote.description,
      etag: currentNote.tag || ""
    });
    setIsModalOpen(true);
  };

  const handleClick = async () => {
    try {
      const success = await editNote(note.id, note.etitle, note.edescription, note.etag);
      if (success) {
        setIsModalOpen(false);
        props.showAlert("Note updated successfully! ✨", "success");
      } else {
        props.showAlert("Failed to update note. Please try again.", "danger");
      }
    } catch (error) {
      console.error('Error updating note:', error);
      props.showAlert("Failed to update note. Please try again.", "danger");
    }
  };
  
  const onChange = (e) => {
    setNote({ ...note, [e.target.name]: e.target.value });
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  // Get unique tags from notes
  const getAllTags = () => {
    const tags = new Set();
    notes.forEach(note => {
      if (note.tag && note.tag.trim()) {
        tags.add(note.tag.trim());
      }
    });
    return Array.from(tags).sort();
  };

  // Filter notes based on search and tag
  const getFilteredNotes = () => {
    return notes.filter(note => {
      const matchesSearch = !searchTerm || 
        note.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        note.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (note.tag && note.tag.toLowerCase().includes(searchTerm.toLowerCase()));
      
      const matchesTag = !selectedTag || note.tag === selectedTag;
      
      return matchesSearch && matchesTag;
    });
  };

  const filteredNotes = getFilteredNotes();
  const availableTags = getAllTags();

  const clearFilters = () => {
    setSearchTerm("");
    setSelectedTag("");
  };

  // Handle keyboard events for modal
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === 'Escape' && isModalOpen) {
        closeModal();
      }
    };

    if (isModalOpen) {
      document.addEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    };
  }, [isModalOpen]);

  return (
    <div className="notes-container">
      <AddNote showAlert={props.showAlert} />
      
      {/* Search and Filter Section */}
      <div className="search-filter-section">
        <div className="search-filter-header">
          <h3>
            <i className="fas fa-search me-2"></i>Find Your Notes
          </h3>
          <p className="text-muted">Search through your thoughts and ideas</p>
        </div>
        
        <div className="filter-row">
          {/* Search Input */}
          <div className="search-input-group">
            <div className="search-wrapper">
              <i className="fas fa-search search-icon"></i>
              <input
                type="text"
                className="form-control search-input"
                placeholder="Search by title, content, or tag..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              {searchTerm && (
                <button
                  className="search-clear-btn"
                  onClick={() => setSearchTerm("")}
                  title="Clear search"
                  aria-label="Clear search"
                >
                  <i className="fas fa-times"></i>
                </button>
              )}
            </div>
          </div>

          {/* Tag Filter */}
          <div className="tag-filter-group">
            <select
              className="form-select"
              value={selectedTag}
              onChange={(e) => setSelectedTag(e.target.value)}
            >
              <option value="">All Tags</option>
              {availableTags.map((tag, index) => (
                <option key={index} value={tag}>
                  {tag}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Active Filters Display */}
        {(searchTerm || selectedTag) && (
          <div className="active-filters">
            <div className="filter-badges">
              <small className="text-muted me-2">Active filters:</small>
              {searchTerm && (
                <span className="badge badge-primary">
                  <i className="fas fa-search me-1"></i>
                  "{searchTerm}"
                </span>
              )}
              {selectedTag && (
                <span className="badge badge-info">
                  <i className="fas fa-tag me-1"></i>
                  {selectedTag}
                </span>
              )}
            </div>
            <button
              className="btn btn-outline-secondary btn-sm"
              onClick={clearFilters}
            >
              <i className="fas fa-times me-1"></i>Clear All
            </button>
          </div>
        )}
      </div>

      {/* Notes Statistics */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">
            <i className="fas fa-sticky-note"></i>
          </div>
          <div className="stat-number">{notes.length}</div>
          <div className="stat-label">Total Notes</div>
        </div>
        
        <div className="stat-card">
          <div className="stat-icon">
            <i className="fas fa-filter"></i>
          </div>
          <div className="stat-number">{filteredNotes.length}</div>
          <div className="stat-label">Showing</div>
        </div>
        
        <div className="stat-card">
          <div className="stat-icon">
            <i className="fas fa-tags"></i>
          </div>
          <div className="stat-number">{availableTags.length}</div>
          <div className="stat-label">Unique Tags</div>
        </div>
        
        <div className="stat-card">
          <div className="stat-icon">
            <i className="fas fa-font"></i>
          </div>
          <div className="stat-number">
            {Math.round(notes.reduce((total, note) => total + (note.description?.length || 0), 0) / 1000)}k
          </div>
          <div className="stat-label">Characters</div>
        </div>
      </div>

      {/* Notes Display */}
      <div className="notes-section">
        <div className="notes-header">
          <h2>
            <i className="fas fa-book-open me-2"></i>
            Your Digital Journal
          </h2>
          <div className="notes-count">
            {filteredNotes.length === notes.length ? (
              <span>{notes.length} {notes.length === 1 ? 'note' : 'notes'}</span>
            ) : (
              <span>
                Showing {filteredNotes.length} of {notes.length} {notes.length === 1 ? 'note' : 'notes'}
              </span>
            )}
          </div>
        </div>
        
        <div className="notes-grid">
          {filteredNotes.length === 0 && notes.length === 0 && (
            <div className="empty-state">
              <div className="empty-state-icon">
                <i className="fas fa-book-open"></i>
              </div>
              <h3>Your journal awaits</h3>
              <p>Start documenting your thoughts, ideas, and experiences. Create your first note above!</p>
              <div className="empty-state-features">
                <div className="feature">
                  <i className="fas fa-shield-alt"></i>
                  <span>Secure & Private</span>
                </div>
                <div className="feature">
                  <i className="fas fa-sync"></i>
                  <span>Auto-saved</span>
                </div>
                <div className="feature">
                  <i className="fas fa-search"></i>
                  <span>Searchable</span>
                </div>
              </div>
            </div>
          )}
          
          {filteredNotes.length === 0 && notes.length > 0 && (
            <div className="empty-state">
              <div className="empty-state-icon">
                <i className="fas fa-search"></i>
              </div>
              <h3>No notes match your search</h3>
              <p>Try adjusting your search terms or clearing filters to see more results.</p>
              <button className="btn btn-outline-primary" onClick={clearFilters}>
                <i className="fas fa-times me-2"></i>Clear Filters
              </button>
            </div>
          )}
          
          {filteredNotes.map((note) => (
            <Noteitem
              key={note._id}
              updateNote={updateNote}
              note={note}
              showAlert={props.showAlert}
            />
          ))}
        </div>
      </div>

      {/* Edit Note Modal */}
      {isModalOpen && (
        <div className="modal show" onClick={closeModal}>
          <div className="modal-dialog" onClick={(e) => e.stopPropagation()}>
            <div className="modal-content">
              <div className="modal-header">
                <h3>
                  <i className="fas fa-edit me-2"></i>Edit Note
                </h3>
                <button
                  className="btn-close"
                  onClick={closeModal}
                  aria-label="Close modal"
                >
                  <i className="fas fa-times"></i>
                </button>
              </div>
              
              <div className="modal-body">
                <form>
                  <div className="form-group">
                    <label htmlFor="etitle" className="form-label">
                      <i className="fas fa-heading me-2"></i>Title
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="etitle"
                      name="etitle"
                      value={note.etitle}
                      onChange={onChange}
                      required
                    />
                  </div>
                  
                  <div className="form-group">
                    <label htmlFor="edescription" className="form-label">
                      <i className="fas fa-align-left me-2"></i>Content
                    </label>
                    <textarea
                      className="form-control"
                      id="edescription"
                      name="edescription"
                      value={note.edescription}
                      onChange={onChange}
                      rows="8"
                      required
                    />
                    <div className="form-text">
                      Characters: {note.edescription.length}
                    </div>
                  </div>
                  
                  <div className="form-group">
                    <label htmlFor="etag" className="form-label">
                      <i className="fas fa-tag me-2"></i>Tag
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="etag"
                      name="etag"
                      value={note.etag}
                      onChange={onChange}
                      placeholder="Enter a tag"
                    />
                  </div>
                </form>
              </div>
              
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={closeModal}
                >
                  <i className="fas fa-times me-2"></i>Cancel
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleClick}
                  disabled={note.etitle.length < 5 || note.edescription.length < 5}
                >
                  <i className="fas fa-save me-2"></i>Update Note
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Notes;
